changeSet.sql:
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END
$$ language 'plpgsql';

CREATE TRIGGER users_updated_at_trigger
BEFORE UPDATE ON users
FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER clients_updated_at_trigger
BEFORE UPDATE ON clients
FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER repairs_updated_at_trigger
BEFORE UPDATE ON repairs
FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

rollback.sql:
DROP TRIGGER IF EXISTS users_updated_at_trigger ON users;
DROP TRIGGER IF EXISTS clients_updated_at_trigger ON clients;
DROP TRIGGER IF EXISTS repairs_updated_at_trigger ON repairs;
DROP FUNCTION IF EXISTS update_updated_at_column();
